import { JSDOM } from 'jsdom';

const dom = new JSDOM(
  `<!doctype html><body>
    <div class="chessground" id="board-1"></div>
    <div class="chessground" id="board-2"></div>
    <div class="chessground" id="board-3"></div>
  </body>`,
  { pretendToBeVisual: true, runScripts: 'outside-only', url: 'http://localhost/' },
);

globalThis.window = dom.window;
globalThis.document = dom.window.document;
globalThis.navigator = dom.window.navigator;
globalThis.requestAnimationFrame = dom.window.requestAnimationFrame.bind(dom.window);
globalThis.performance = dom.window.performance;

const { Chessground } = await import('./dist/chessground.js');

const board1 = document.getElementById('board-1');
const board2 = document.getElementById('board-2');
const board3 = document.getElementById('board-3');

// Mimic demo.html
const api1 = Chessground(board1, {});
const api2 = Chessground(board2, { fen: 'r2q2k1/1p6/p2p4/2pN1rp1/N1Pb2Q1/8/PP1B4/R6K b - - 2 25' });
const api3 = Chessground(board3, {
  drawable: {
    autoShapes: [{ orig: 'a2', dest: 'a6', brush: 'green' }],
  },
});

console.log('defaults loaded, eraseOnClick =', api1.state.drawable.eraseOnClick);
console.log('api1 fen =', api1.getFen());
console.log('api3 autoShapes =', api3.state.drawable.autoShapes.length);
console.log('api2 turnColor =', api2.state.turnColor);
console.log('SMOKE OK');

